// Shape/use variants, never palette duplicates. Each row is a compact saved
// type ID; colours continue to use the existing palette setting.
const definitions=[];
function group(section,family,rows,options={}){
  for(const row of rows.trim().split('\n')){
    const [id,name,design,size,mount='floor']=row.trim().split('|'),[w,h,d]=size.split(',').map(Number);
    const extra=typeof options==='function'?options({id,design,w,h,d,mount}):options;
    definitions.push({id,name,design,w,h,d,mount,family,section,extended:true,...extra});
  }
}
